'use strict';

const fs = require('fs');
const path = require('path');

const frontendDir = path.resolve(__dirname, '..');
const storeDir = path.join(frontendDir, 'store');
const adminDir = path.join(frontendDir, 'admin');
const outputDir = path.join(frontendDir, 'public');
const markerName = '.rainbow-colors-static-output';
const markerText = [
  'Generated by frontend/scripts/build-static.js.',
  'This directory is disposable build output and is safe to regenerate.',
  ''
].join('\n');
const archiveExtensions = new Set(['.zip', '.tar', '.gz', '.tgz', '.7z', '.rar', '.jar', '.war']);
const excludedSourceFiles = new Set([
  path.join(storeDir, 'css', 'rainbow-colors-store.zip')
]);

function fail(message) {
  console.error(`Static build failed: ${message}`);
  process.exit(1);
}

function isExcludedSourcePath(sourcePath) {
  const resolvedPath = path.resolve(sourcePath);
  return (
    excludedSourceFiles.has(resolvedPath) ||
    archiveExtensions.has(path.extname(resolvedPath).toLowerCase())
  );
}

function assertSafeOutputPath() {
  if (path.basename(outputDir) !== 'public') {
    fail(`Refusing unexpected output directory: ${outputDir}`);
  }

  if (outputDir === frontendDir || !outputDir.startsWith(frontendDir + path.sep)) {
    fail(`Refusing output directory outside frontend: ${outputDir}`);
  }

  if (!fs.existsSync(outputDir)) {
    return;
  }

  const stat = fs.lstatSync(outputDir);
  if (stat.isSymbolicLink()) {
    fail(`Refusing to clean symlinked output directory: ${outputDir}`);
  }
  if (!stat.isDirectory()) {
    fail(`Output path exists but is not a directory: ${outputDir}`);
  }

  const entries = fs.readdirSync(outputDir);
  if (entries.length === 0) {
    return;
  }

  const markerPath = path.join(outputDir, markerName);
  const marker = fs.existsSync(markerPath)
    ? fs.readFileSync(markerPath, 'utf8')
    : '';

  if (!marker.includes('Generated by frontend/scripts/build-static.js.')) {
    fail(
      `Output directory is not empty and is not recognized as generated output: ${outputDir}\n` +
      'Inspect it and remove it manually only if you are certain it contains no user files.'
    );
  }
}

function copyContents(sourceDir, targetDir) {
  if (!fs.existsSync(sourceDir) || !fs.statSync(sourceDir).isDirectory()) {
    fail(`Missing source directory: ${sourceDir}`);
  }

  fs.mkdirSync(targetDir, { recursive: true });

  for (const entry of fs.readdirSync(sourceDir, { withFileTypes: true })) {
    const sourcePath = path.join(sourceDir, entry.name);
    const targetPath = path.join(targetDir, entry.name);

    if (isExcludedSourcePath(sourcePath)) {
      console.warn(`Excluded from static output: ${path.relative(frontendDir, sourcePath)}`);
      continue;
    }

    if (fs.existsSync(targetPath)) {
      fail(`Refusing to overwrite existing output: ${targetPath}`);
    }

    fs.cpSync(sourcePath, targetPath, {
      recursive: true,
      force: false,
      errorOnExist: true,
      filter: (nestedSourcePath) => {
        if (isExcludedSourcePath(nestedSourcePath)) {
          console.warn(
            `Excluded from static output: ${path.relative(frontendDir, nestedSourcePath)}`
          );
          return false;
        }
        return true;
      }
    });
  }
}

function walkFiles(dir, baseDir = dir, files = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkFiles(fullPath, baseDir, files);
    } else {
      files.push(path.relative(baseDir, fullPath));
    }
  }
  return files;
}

function assertNoForbiddenFiles() {
  const files = walkFiles(outputDir);
  const forbiddenDirs = new Set(['node_modules', 'backend', '.git', '.vercel']);

  for (const relativePath of files) {
    const segments = relativePath.split(path.sep);
    const name = segments[segments.length - 1];

    if (segments.some((segment) => forbiddenDirs.has(segment))) {
      fail(`Forbidden path copied into public output: ${relativePath}`);
    }
    if (name === '.env' || name.startsWith('.env.')) {
      fail(`Environment file copied into public output: ${relativePath}`);
    }
    if (archiveExtensions.has(path.extname(name).toLowerCase())) {
      fail(`Archive copied into public output: ${relativePath}`);
    }
  }
}

function assertRequiredOutput() {
  const requiredPaths = [
    'index.html',
    'css/style.css',
    'js/main.js',
    'images',
    path.join('admin', 'index.html'),
    path.join('admin', 'css', 'admin.css'),
    path.join('admin', 'js', 'admin.js'),
    path.join('admin', 'images')
  ];

  for (const requiredPath of requiredPaths) {
    if (!fs.existsSync(path.join(outputDir, requiredPath))) {
      fail(`Missing required output path: ${requiredPath}`);
    }
  }
}

function main() {
  assertSafeOutputPath();

  if (!fs.existsSync(path.join(storeDir, 'index.html'))) {
    fail(`Missing Store entry point: ${path.join(storeDir, 'index.html')}`);
  }
  if (!fs.existsSync(path.join(adminDir, 'index.html'))) {
    fail(`Missing Admin entry point: ${path.join(adminDir, 'index.html')}`);
  }
  if (!fs.existsSync(path.join(storeDir, 'images'))) {
    fail(`Missing Store images directory: ${path.join(storeDir, 'images')}`);
  }

  if (fs.existsSync(outputDir)) {
    fs.rmSync(outputDir, { recursive: true, force: true });
  }
  fs.mkdirSync(outputDir, { recursive: true });
  fs.writeFileSync(path.join(outputDir, markerName), markerText, 'utf8');

  copyContents(storeDir, outputDir);
  copyContents(adminDir, path.join(outputDir, 'admin'));

  const adminSourceImages = path.join(adminDir, 'images');
  if (fs.existsSync(adminSourceImages)) {
    console.warn(
      'Admin has its own images directory; store images were not mirrored into admin/images.'
    );
  } else {
    copyContents(
      path.join(storeDir, 'images'),
      path.join(outputDir, 'admin', 'images')
    );
  }

  assertRequiredOutput();
  assertNoForbiddenFiles();

  const files = walkFiles(outputDir);
  const totalBytes = files.reduce(
    (sum, relativePath) => sum + fs.statSync(path.join(outputDir, relativePath)).size,
    0
  );

  console.log('Static build completed.');
  console.log(`  output: ${path.relative(frontendDir, outputDir)}`);
  console.log(`  files: ${files.length}`);
  console.log(`  bytes: ${totalBytes}`);
  console.log(`  store: ${path.relative(frontendDir, storeDir)}`);
  console.log(`  admin: ${path.relative(frontendDir, adminDir)}`);
  console.log(
    '  admin image mirror: ' +
      (fs.existsSync(adminSourceImages)
        ? 'skipped (admin/images already exists)'
        : 'store/images -> admin/images')
  );
}

main();
